design.css:
/* Onyx — the Nuvio look (docs/theme-references/nuvio.md): near-black, white on black, Roboto, stadium buttons. */

/* Home has no app bar of its own: the featured banner fills the top of the screen and the header floats over it. */
[data-slot="home.header"] { position: absolute; inset: 0 0 auto; z-index: 5; background: linear-gradient(to bottom, rgba(13, 13, 13, 0.6), rgba(13, 13, 13, 0)); }
@media (max-width: 640px) { [data-slot="home.hero"] { margin-top: calc(-1 * env(safe-area-inset-top, 0px)) !important; } }

/* Featured banner: square top corners, 28 px bottom corners, a seven-stop fade into the page. */
[data-slot="home.hero"] { border-radius: 0 0 28px 28px; overflow: hidden; }
[data-part="onyx.hero"]::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(13, 13, 13, 0) 0%, rgba(13, 13, 13, 0.04) 16%, rgba(13, 13, 13, 0.14) 32%, rgba(13, 13, 13, 0.34) 50%, rgba(13, 13, 13, 0.6) 68%, rgba(13, 13, 13, 0.86) 84%, #0d0d0d 100%) !important;
  pointer-events: none;
}
[data-part="onyx.hero"]::after { z-index: 1; }
[data-part="onyx.hero"] > :not(:first-child) { z-index: 2; }
[data-part="onyx.logo"] img { max-height: 92px; object-fit: contain; }
[data-part="onyx.details"] { padding: 0 28px; }
/* Slide markers are drawn on the marker's track; the button around it keeps its hit area unpainted. */
[data-part="hero.dot.track"] { width: 8px !important; height: 8px !important; border-radius: 999px !important; background: rgba(245, 247, 248, 0.35) !important; }
[data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: 32px !important; background: #f5f7f8 !important; }

/* Rows. */
[data-part="row.title"], [data-part="block.title"] { font-size: 20px; font-weight: 700; color: #f5f7f8; }

/* ── Series page: Nuvio MetaDetailsScreen (docs/theme-references/nuvio-series.md) ── */
/* Built on the real API 3 hooks: episodes.seasons/season*, episodes.toolbar/more, detail.sections
   (stack)/detail.section*, detail.title:"logo"/detail.logo, detail.byline, detail.airing. Two
   selectors below still fall back to a documented-hook-scoped `:has()` because no hook covers the
   episode-carousel scroller or the phone "Information" grid wrapper yet — see the report. */

/* Hero: clamp(420px, 133vw, 760px) tall, a 7-stop fade 320 px up from the bottom. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] {
  height: clamp(420px, 133vw, 760px);
  min-height: 0;
  max-height: none;
  margin-bottom: -72px;
}
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] > img { object-position: center !important; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] > div { display: none; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"]::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 320px;
  pointer-events: none;
  background-image: linear-gradient(to bottom, rgba(13, 13, 13, 0) 0%, rgba(13, 13, 13, 0.04) 16%, rgba(13, 13, 13, 0.14) 32%, rgba(13, 13, 13, 0.34) 50%, rgba(13, 13, 13, 0.62) 68%, rgba(13, 13, 13, 0.84) 84%, #0d0d0d 100%);
}

/* No poster card. The title (`detail.title: "logo"` shows the title logo natively — no duplicate
   header artwork or :has() needed) and the genre line sit centred over the hero's lower fade. */
[data-slot="detail"] [data-part="detail.poster"],
[data-slot="detail"] [data-part="detail.alt-title"] { display: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.title"] {
  position: relative;
  z-index: 1;
  text-align: center;
  font-size: 38px;
  line-height: 42px;
  font-weight: 700;
  letter-spacing: -1.2px;
  -webkit-line-clamp: 3;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.logo"] {
  display: block;
  width: 60%;
  height: 80px;
  margin-inline: auto;
  object-fit: contain;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.header"] { position: relative; z-index: 1; margin-top: 8px; }
[data-slot="detail"][data-variant="phone"] [data-part="onyx.genres"] { line-height: 20px; }

/* One-row Play pill + a couple of 52 px circles (Save, then the ⋯ overflow); Share is hidden
   (Nuvio has neither). Pulling `detail.actions` up over the Play row is still the only way to
   merge them into one line — API 3 has no single actions-cluster hook (reported below). */
[data-slot="detail"] [data-part="button"][data-variant="primary"] { border-radius: 40px; background: #f5f7f8; color: #0d0d0d; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] svg { fill: currentColor; }
[data-slot="detail"][data-variant="phone"] [data-part="button"][data-variant="primary"] {
  width: calc(100% - 128px);
  height: 52px;
  margin-top: 8px;
  padding: 0 16px;
  gap: 8px;
  font-family: var(--font-display);
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  letter-spacing: 0.1px;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] { width: max-content; margin: -52px 0 0 auto; gap: 12px; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button {
  flex: 0 0 52px;
  width: 52px;
  height: 52px;
  padding: 0;
  gap: 0;
  border-radius: 999px;
  background: #222222;
  color: #f5f7f8;
  font-size: 0;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > [data-part="button"][data-variant="icon"] { display: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[aria-haspopup] { background: rgba(34, 34, 34, 0.82); }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[aria-haspopup] svg { transition: transform 240ms cubic-bezier(0.4, 0, 0.2, 1); }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[aria-expanded="true"] { background: #f5f7f8; color: #0d0d0d; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[aria-expanded="true"] svg { transform: rotate(90deg); }

/* Stacked sections (`detail.sections.mode: "stack"`): 20 / 600 titles, 20 px between sections, no
   tab strip at all — so the old tab-bar styling is gone along with it. */
[data-slot="detail.section"] { margin-top: 20px; }
[data-slot="detail.section"]:first-of-type { margin-top: 0; }
[data-part="detail.section-title"] {
  margin-bottom: 14px;
  font-family: var(--font-heading);
  font-size: 20px;
  line-height: 24px;
  font-weight: 600;
  color: #f5f7f8;
}

/* Overview section: the compact meta row (year/runtime/badge/score are the built-in `detail.meta`
   composition on phones — the custom Nuvio `facts` template only renders on desktop, see report),
   no genre rail (already in the hero), no release-timing line, full-strength description. */
[data-slot="detail"] [data-part="detail.meta"] {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 700;
  color: #f5f7f8;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"] { display: none; }
[data-part="detail.airing"] { display: none; }
[data-slot="detail"] [data-part="detail.synopsis"] { color: #f5f7f8; font-size: 14px; line-height: 22px; }

/* The phone Overview "Information" grid: strip the rounded-card look for a quiet declutter toward
   Nuvio's Show Details table (right-aligned values, a hairline rule, no shading). */
[data-slot="detail.section"][data-section="overview"] [data-part="fact"] {
  border-radius: 0;
  background: transparent;
  padding: 10px 0;
  border-bottom: 1px solid rgba(245, 247, 248, 0.1);
}
[data-slot="detail.section"][data-section="overview"] [data-part="fact.label"] {
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
  color: rgba(245, 247, 248, 0.8);
}
[data-slot="detail.section"][data-section="overview"] [data-part="fact.value"] {
  margin-top: 2px;
  font-weight: 500;
  color: #f5f7f8;
}

/* Cast section: circular avatars with a name/role caption, closer to Nuvio's 80 px rail than
   izumi's bordered photo-left rows (it stays a grid — no rail-arrangement hook for people yet). */
[data-section="characters"] [data-part="person"] {
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  text-align: center;
}
[data-section="characters"] [data-part="person.photo"] {
  width: 80px;
  height: 80px;
  aspect-ratio: 1 / 1;
  border-radius: 999px;
  object-fit: cover;
}
[data-section="characters"] [data-part="person.name"] { font-size: 14px; font-weight: 700; color: #f5f7f8; }
[data-section="characters"] [data-part="person.role"] { font-size: 12px; color: #969ca3; text-transform: capitalize; }

/* Season picker (`detail.episodes.seasons: "posters"`), Nuvio §2.3-2.4: 100 × 150 tiles, radius 8,
   a 1 px / 2 px border, a "Seasons" heading (no hook for that text — added as content on the
   documented `episodes.seasons` slot, not matched by aria-label or structure).
   The heading is reserved as top PADDING, not a negative-offset ::before: the picker sets
   `overflow-x: auto` for its own horizontal scroll, and per the CSS Overflow spec a lone
   non-"visible" axis forces the other axis to "auto" too, so anything positioned outside the
   box on Y (confirmed live: a -30px ::before) is clipped away rather than shown above it. */
[data-slot="episodes.seasons"][data-variant="posters"] { padding-top: 30px; gap: 16px; }
[data-slot="episodes.seasons"][data-variant="posters"]::before {
  content: "Seasons";
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-heading);
  font-size: 18px;
  line-height: 24px;
  font-weight: 600;
  color: #f5f7f8;
}
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season"] { width: 100px; }
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season.art"] {
  border-radius: 8px;
  background: rgba(34, 34, 34, 0.5);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.1);
}
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season"][data-active] [data-part="season.art"] { box-shadow: inset 0 0 0 2px #f5f7f8; }
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season.label"] { font-size: 15px; font-weight: 600; color: #969ca3; }
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season"][data-active] [data-part="season.label"] { font-weight: 700; color: #f5f7f8; }

/* Episode toolbar: `controls: []` and `order: "none"` leave nothing inline and drop sort from the
   overflow entirely — Nuvio has neither. Only the small overflow button (download/queue) remains. */
[data-slot="episodes.toolbar"][data-variant="bar"] { margin-bottom: 8px; justify-content: flex-end; }
[data-part="episodes.more"] { width: 36px; height: 36px; border-radius: 999px; background: rgba(34, 34, 34, 0.6); color: #969ca3; }
[data-part="episodes.more"] svg { width: 16px; height: 16px; }

/* The episode carousel row: bleeds to the screen edges with a 12 px gap. There is still no hook for
   the scroller/track itself, so this reaches it via :has() scoped to the documented `episode` part
   (structural containment, not text/aria matching) rather than any Tailwind class. */
[data-slot="detail.episodes"] div:has(> [data-part="episode"][data-variant="template"]) { gap: 12px; scrollbar-width: none; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] div:has(> [data-part="episode"][data-variant="template"]) {
  margin-inline: -16px;
  padding: 0 16px 4px;
  scroll-padding-inline: 16px;
}

/* The Nuvio horizontal episode card (template parts). */
[data-slot="detail.episodes"] [data-part="episode"][data-variant="template"] {
  overflow: hidden;
  border-radius: 12px;
  background: rgba(34, 34, 34, 0.45);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
}
[data-part="onyx.ep"] { height: 184px; }
[data-part="onyx.ep-art"]::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(to bottom, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0) 42%, rgba(0, 0, 0, 0.2) 56%, rgba(0, 0, 0, 0.45) 70%, rgba(0, 0, 0, 0.68) 84%, rgba(0, 0, 0, 0.92) 100%);
}
[data-part="onyx.ep-watched"] { width: 20px; height: 20px; margin: 10px; border-radius: 999px; background: #f5f7f8; display: grid; place-items: center; }
[data-part="onyx.ep-watched-mark"] { font-size: 11px; font-weight: 900; line-height: 1; color: #111111; }
[data-part="onyx.ep-info"] { padding-bottom: 12px; }
[data-part="onyx.ep-code"] { display: inline-block; padding: 3px 7px; border-radius: 5px; background: rgba(0, 0, 0, 0.42); font-size: 9px; line-height: 12px; letter-spacing: 0; }
[data-part="onyx.ep-title"] { line-height: 19px; }
[data-part="onyx.ep-overview"] { font-family: var(--font-display); line-height: 15px; letter-spacing: 0.4px; }
[data-part="onyx.ep-meta"] { font-family: var(--font-display); line-height: 16px; letter-spacing: 0.5px; }
[data-part="onyx.ep-date"] { margin-inline-start: auto; }
/* The meter's own scoped styles compile to (0,2,0)/(0,3,1); this three-attribute chain matches R8's
   original approach to outrank them (a tie is broken by the theme stylesheet loading last). */
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="onyx.ep-progress"] { height: 4px; margin-top: 2px; background: rgba(255, 255, 255, 0.22); }
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="onyx.ep-progress"] > span { background: #f5f5f5; }

/* Desktop: a 56 px Play, a larger logo, and the same full-strength description. */
[data-slot="detail"][data-variant="desktop"] [data-part="button"][data-variant="primary"] { height: 56px; padding: 0 28px; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.title"] { text-align: start; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.logo"] { width: auto; height: 72px; object-position: left center; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.header"] { margin-top: 8px; }
[data-slot="detail"][data-variant="desktop"] [data-part="onyx.genres"] { text-align: start; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.synopsis"] { -webkit-line-clamp: 3; color: #f5f7f8; font-size: 14px; line-height: 22px; }
[data-part="onyx.badge"] { padding: 4px 8px; border: 1px solid rgba(150, 156, 163, 0.55); border-radius: 6px; line-height: 14px; letter-spacing: 0.8px; }

/* Desktop client bug (confirmed live, reported below): with `actionsFirst: true` and a stacked
   Overview section, AnimeDetail.svelte shows the description twice — once under the actions
   (desktop has no equivalent of the phone `sections.info` toggle) and again inside the stacked
   Overview section. Drop the second one; the first already sits where Nuvio wants it. */
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.section"][data-section="overview"] [data-part="detail.synopsis"] { display: none; }
